@startuml structural

enum OrderStatus {
    submitted
    pending
    filled
    shipped
    closed
}

enum InvoiceStatus {
    issued
    paid
}

enum PaymentStatus {
    pending
    completed
    failed
}

enum PaymentMethod {
    bank
    card
    cash
}

class Customer {
    +String name
    +String address
    +String phoneNumber
    +String? bankAccount
}

class Product {
    +String name
    +String description
    +Decimal price
    +String imageUrl
}

class Order {
    +DateTime orderDate
    +Decimal totalAmount
    +OrderStatus status
    +PaymentMethod paymentMethod
}

class OrderItem {
    +int quantity
    +Decimal unitPrice
}

class Invoice {
    +DateTime date
    +Decimal amount
    +InvoiceStatus status
    +PaymentMethod paymentMethod
}

class Payment {
    +DateTime date
    +Decimal amount
    +PaymentStatus status
    +PaymentMethod paymentMethod
}

Customer "1" o-- "*" Order : places >
Order "1" o-- "*" OrderItem : contains >
OrderItem "1" --> "1" Product : refers to >
Order "1" o-- "0..1" Invoice : has >
Invoice "1" o-- "*" Payment : receives >

@enduml

