  "requirements": [
    {
      "id": "US-01",
      "type": "functional",
      "statement": "As a Customer, I want to create and maintain my personal profile, so that the system can identify me and contact me when needed.",
      "acceptance_criteria": [
        {"id": "US-01-AC01", "format": "condition", "text": "The profile shall store a name, an address and a phone number (REQ-F-01) and may store at most one bank account (REQ-F-02)."},
        {"id": "US-01-AC02", "format": "condition", "text": "All stored attributes are mandatory except the bank account (REQ-F-45)."},
