      ]
    },
    {
      "id": "US-02",
      "type": "functional",
      "statement": "As an OrderStaff, I want to add new products to the catalogue, so that customers can order them.",
      "acceptance_criteria": [
        {"id": "US-02-AC01", "format": "condition", "text": "Each product shall have a name, description, price and image (REQ-F-03) stored as decimal for price (REQ-F-46)."},
        {"id": "US-02-AC02", "format": "condition", "text": "All product attributes are mandatory (REQ-F-45)."},
        {"id": "US-02-AC03", "format": "given_when_then", "text": "Given a product creation request with valid data, when the system stores the product, then the product becomes available for order items."}
      ]
    },
