        {"id": "US-03-AC04", "format": "given_when_then", "text": "Given an order submission where the customer is unknown, when the system validates the request, then the order is rejected and no record is created (REQ-F-14)."},
        {"id": "US-03-AC05", "format": "given_when_then", "text": "Given an order submission containing a non‑existent product, when the system validates the items, then the order is rejected and no record is created (REQ-F-16)."}
      ]
    },
