        {"id": "US-04-AC02", "format": "given_when_then", "text": "Given an order with status submitted, when OrderStaff selects “receive”, then the order status becomes pending (REQ-F-18)."},
        {"id": "US-04-AC03", "format": "given_when_then", "text": "Given an order whose status is not submitted, when OrderStaff attempts to receive it, then the request is rejected and the status remains unchanged (REQ-F-19)."}
