        {"id": "US-06-AC02", "format": "given_when_then", "text": "Given a pending order, when OrderStaff selects “decline”, then the order status becomes closed (REQ-F-22)."},
        {"id": "US-06-AC03", "format": "given_when_then", "text": "Given an order not in pending status, when OrderStaff attempts to decline it, then the request is rejected and the status remains unchanged (REQ-F-23)."}
      ]
    },
