        {"id": "US-07-AC02", "format": "given_when_then", "text": "Given a filled order, when OrderStaff selects “ship”, then the order status becomes shipped (REQ-F-25)."},
        {"id": "US-07-AC03", "format": "given_when_then", "text": "Given an order whose status is not filled, when OrderStaff attempts to ship it, then the request is rejected and the status stays unchanged (REQ-F-26)."}
      ]
    },
