        {"id": "US-08-AC03", "format": "given_when_then", "text": "Given an eligible order, when Accountant creates the invoice with date, amount, payment method, then the invoice is linked to the order and its status is issued."},
        {"id": "US-08-AC04", "format": "given_when_then", "text": "Given an order that is declined, when Accountant attempts to raise an invoice, then the request is rejected (REQ-F-24)."},
        {"id": "US-08-AC05", "format": "given_when_then", "text": "Given an order whose status is submitted, pending or closed, when Accountant attempts to raise an invoice, then the request is rejected (REQ-F-30)."}
      ]
    },
    {
      "id": "US-09",
      "type": "functional",
      "statement": "As an Accountant, I want to record a payment against an issued invoice, so that the invoice can be settled.",
      "acceptance_criteria": [
        {"id": "US-09-AC01", "format": "condition", "text": "Payments may be recorded only against invoices with status issued (REQ-F-32) and the payment status starts as pending (REQ-F-35)."},
        {"id": "US-09-AC02", "format": "given_when_then", "text": "Given an invoice with status issued, when Accountant records a payment with date, amount and method, then a payment entity is created with status pending."},
        {"id": "US-09-AC03", "format": "given_when_then", "text": "Given an invoice with status paid, when a payment is submitted, then the request is rejected (REQ-F-33)."},
        {"id": "US-09-AC04", "format": "given_when_then", "text": "Given a failed payment, when a further payment is submitted, then the new payment is created with status pending while the failed one remains failed (REQ-F-34)."},
        {"id": "US-09-AC05", "format": "given_when_then", "text": "Given a pending payment, when Accountant confirms it, then the payment status becomes completed (REQ-F-35) and the invoice status becomes paid (REQ-F-36)."},
        {"id": "US-09-AC06", "format": "given_when_then", "text": "Given a pending payment, when Accountant rejects it, then the payment status becomes failed (REQ-F-38) and invoice and order statuses remain unchanged."},
        {"id": "US-09-AC07", "format": "condition", "text": "Payment status may change only from pending to completed or to failed (REQ-F-50)."}
      ]
    },
    {
      "id": "US-10",
      "type": "functional",
      "statement": "As an OrderStaff, I want to close a shipped order whose invoice is paid, so that the order lifecycle is finished.",
      "acceptance_criteria": [
        {"id": "US-10-AC01", "format": "condition", "text": "An order may change from shipped to closed only when its linked invoice status is paid (REQ-F-40)."},
        {"id": "US-10-AC02", "format": "given_when_then", "text": "Given a shipped order with a paid invoice, when OrderStaff selects “close”, then the order status becomes closed (REQ-F-40)."},
        {"id": "US-10-AC03", "format": "given_when_then", "text": "Given a shipped order whose invoice is not paid, when OrderStaff attempts to close it, then the request is rejected and the status stays unchanged (REQ-F-41)."},
        {"id": "US-10-AC04", "format": "given_when_then", "text": "Given an order whose invoice is paid but whose status is not shipped, when OrderStaff attempts to close it, then the request is rejected (REQ-F-42)."},
