{"encoding":"utf-8","end_line":1,"path":"structural.puml","replacement":"@startuml structural
' Enums
enum OrderStatus {
  submitted
  pending
  filled
  shipped
  closed
}

enum InvoiceStatus {
  issued
  paid
}

enum PaymentStatus {
  pending
  completed
  failed
}

enum PaymentMethod {
  bank
  card
  cash
}

' Classes
class Customer {
  +id: UUID
  +name: String
  +address: String
  +phone: String
  +bankAccount: BankAccount [0..1]
}

class BankAccount {
  +accountNumber: String
  +bankName: String
}

class Product {
  +id: UUID
  +name: String
  +description: String
  +price: Decimal
  +imageUrl: String
}

class Order {
  +id: UUID
  +orderDate: Date
  +totalAmount: Decimal
  +status: OrderStatus
  +paymentMethod: PaymentMethod
}

class OrderItem {
  +quantity: Integer
  +unitPrice: Decimal
}

class Invoice {
  +id: UUID
  +date: Date
  +amount: Decimal
  +status: InvoiceStatus
  +paymentMethod: PaymentMethod
}

class Payment {
  +id: UUID
  +date: Date
  +amount: Decimal
  +status: PaymentStatus
  +paymentMethod: PaymentMethod
}

' Relationships
Customer "1" -- "*" Order : places >
Order "1" *-- "*" OrderItem : contains >
OrderItem "1" --> "1" Product : refers to >
Order "1" o-- "0..1" Invoice : billed by >
Invoice "1" *-- "*" Payment : records >
Customer "1" o-- "0..1" BankAccount : has >
@enduml","start_line":1}

{"encoding":"utf-8","end_line":1,"path":"behavioral.puml","replacement":"@startuml behavioral
|Customer|
start
:Submit Order;
if (Order valid?) then (yes)
  :Create Order [submitted];
else (no)
  stop
endif
|OrderStaff|
if (Receive?) then (yes)
  :Receive Order;
  :Update Order [pending];
else (no)
  stop
endif
if (Fill?) then (yes)
  :Fill Order;
  :Update Order [filled];
else (no)
  stop
endif
if (Decline?) then (yes)
  :Decline Order;
  :Update Order [closed];
else (no)
endif
if (Ship?) then (yes)
  :Ship Order;
  :Update Order [shipped];
else (no)
endif
|Accountant|
if (Raise Invoice?) then (yes)
  :Create Invoice;
  :Link Invoice to Order;
  :Set Invoice [issued];
else (no)
endif
if (Record Payment?) then (yes)
  :Create Payment [pending];
else (no)
endif
if (Confirm Payment?) then (yes)
  :Set Payment [completed];
  :Set Invoice [paid];
else (no)
endif
if (Reject Payment?) then (yes)
  :Set Payment [failed];
else (no)
endif
|OrderStaff|
if (Close Order?) then (yes)
  :Close Order;
  :Set Order [closed];
else (no)
endif
stop
@enduml","start_line":1}

